import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { createServer } from "node:https";
import type { AddressInfo, Socket } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { getCACertificates, setDefaultCACertificates } from "node:tls";
import { expect, it } from "vitest";
import { createFetchUpstream } from "../../src/auth/proxy/index.js";

// Synthetic loopback certificate only, generated by the Docker toolchain.
function certificate(directory: string) {
  execFileSync(
    "openssl",
    [
      "req",
      "-x509",
      "-newkey",
      "ec",
      "-pkeyopt",
      "ec_paramgen_curve:prime256v1",
      "-nodes",
      "-keyout",
      "key.pem",
      "-out",
      "cert.pem",
      "-days",
      "2",
      "-subj",
      "/CN=upstream-test",
      "-addext",
      "subjectAltName=IP:127.0.0.1",
    ],
    { cwd: directory, stdio: "ignore" },
  );
  return {
    key: readFileSync(join(directory, "key.pem")),
    cert: readFileSync(join(directory, "cert.pem"), "utf8"),
  };
}

it.each(["redirect", "oversized", "stalled"])(
  "BR-131 v2 AC-09 real fetch closes refused transports",
  async (kind) => {
    const directory = mkdtempSync(join(tmpdir(), "kdrive-upstream-tls-"));
    const tls = certificate(directory);
    const previous = getCACertificates("default");
    const sockets = new Set<Socket>();
    let closed!: () => void;
    const transportClosed = new Promise<void>((resolve) => {
      closed = resolve;
    });
    const server = createServer(tls, (request, response) => {
      request.socket.once("close", closed);
      response.writeHead(kind === "redirect" ? 302 : 200, {
        "content-type": "application/json",
      });
      response.flushHeaders();
      if (kind === "oversized") response.write(Buffer.alloc(65_537, 0x20));
      // Deliberately never end the body; only the client can release it.
    });
    server.on("connection", (socket) => {
      sockets.add(socket);
      socket.once("close", () => sockets.delete(socket));
    });
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
      setDefaultCACertificates([...previous, tls.cert]);
      await new Promise<void>((resolve) =>
        server.listen(0, "127.0.0.1", resolve),
      );
      const port = (server.address() as AddressInfo).port;
      const upstream = createFetchUpstream({ fetch: globalThis.fetch });
      const message =
        kind === "redirect"
          ? "Upstream redirect refused."
          : kind === "oversized"
            ? "Upstream response too large."
            : "Upstream deadline exceeded.";
      await expect(
        upstream.fetchJson(`https://127.0.0.1:${String(port)}/`),
      ).rejects.toThrow(message);
      await Promise.race([
        transportClosed,
        new Promise<never>((_resolve, reject) => {
          timer = setTimeout(() => {
            reject(new Error("transport remained open"));
          }, 1000);
        }),
      ]);
    } finally {
      clearTimeout(timer);
      setDefaultCACertificates(previous);
      for (const socket of sockets) socket.destroy();
      await new Promise<void>((resolve) => {
        server.close(() => {
          resolve();
        });
      });
      rmSync(directory, { recursive: true, force: true });
    }
  },
  15_000,
);
